1	import { useState } from "react";
2	import { useQuery, useQueryClient } from "@tanstack/react-query";
3	import { supabase } from "@/integrations/supabase/client";
4	import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
5	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
6	import { Button } from "@/components/ui/button";
7	import { Input } from "@/components/ui/input";
8	import { Badge } from "@/components/ui/badge";
9	import { toast } from "sonner";
10	import { Loader2, RefreshCw, CheckCircle, Store } from "lucide-react";
11	import PlansTab from "./PlansTab";
12	import PaymentsTab from "./PaymentsTab";
13	import SubscriptionsSubTab from "./SubscriptionsSubTab";
14	
15	const BillingTab = () => {
16	  const qc = useQueryClient();
17	  const [fetchingBrands, setFetchingBrands] = useState(false);
18	  const [brands, setBrands] = useState<any[] | null>(null);
19	  const [savingBrand, setSavingBrand] = useState(false);
20	
21	  const { data: config } = useQuery({
22	    queryKey: ["platform_config_brand"],
23	    queryFn: async () => {
24	      const { data, error } = await supabase.from("platform_config").select("dodo_brand_id").limit(1).single();
25	      if (error) return null;
26	      return data;
27	    },
28	  });
29	
30	  const fetchBrands = async () => {
31	    setFetchingBrands(true);
32	    try {
33	      const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
34	        body: { action: "fetch_brands" },
35	      });
36	      if (error) throw error;
37	      if (data?.error) throw new Error(data.error);
38	      const brandList = Array.isArray(data?.brands) ? data.brands : data?.brands?.items || [];
39	      setBrands(brandList);
40	      if (brandList.length === 0) toast.info("No brands found on Dodo. Create one in Dodo Dashboard first.");
41	    } catch (err: any) {
42	      toast.error("Failed to fetch brands: " + (err.message || "Unknown error"));
43	    } finally {
44	      setFetchingBrands(false);
45	    }
46	  };
47	
48	  const saveBrandId = async (brandId: string) => {
49	    setSavingBrand(true);
50	    try {
51	      const { error } = await supabase.from("platform_config").update({ dodo_brand_id: brandId } as any).not("id", "is", null);
52	      if (error) throw error;
53	      toast.success("Dodo brand saved ✓");
54	      qc.invalidateQueries({ queryKey: ["platform_config_brand"] });
55	    } catch (err: any) {
56	      toast.error("Failed to save brand: " + (err.message || "Unknown error"));
57	    } finally {
58	      setSavingBrand(false);
59	    }
60	  };
61	
62	  return (
63	    <div className="space-y-4">
64	      <h2 className="text-xl font-semibold">Billing & Plans</h2>
65	
66	      {/* Dodo Brand Config */}
67	      <Card>
68	        <CardHeader className="pb-3">
69	          <CardTitle className="text-sm flex items-center gap-2">
70	            <Store className="h-4 w-4 text-primary" />
71	            Dodo Brand
72	          </CardTitle>
73	        </CardHeader>
74	        <CardContent>
75	          <div className="flex items-center gap-3 flex-wrap">
76	            {config?.dodo_brand_id ? (
