29	const syncDodoProduct = async (action: string, payload: any) => {
30	  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
31	    body: { action, type: "plan", ...payload },
32	  });
33	  if (error) {
34	    const parsed = parseFunctionError(error);
35	    if (parsed?.not_found) return parsed;
36	    throw error;
37	  }
38	  if (data?.not_found) return data;
39	  if (data?.error) throw new Error(data.error);
40	  return data;
41	};
