1	import { useState } from "react";
2	import { useQuery } from "@tanstack/react-query";
3	import { supabase } from "@/integrations/supabase/client";
4	import {
5	  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
6	} from "@/components/ui/table";
7	import { Badge } from "@/components/ui/badge";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Button } from "@/components/ui/button";
10	import { CreditCard, ChevronLeft, ChevronRight, Download, ExternalLink } from "lucide-react";
11	import { exportToCSV } from "@/lib/csvExport";
12	
13	const PAGE_SIZE = 20;
14	
15	const PaymentsTab = () => {
16	  const [page, setPage] = useState(0);
17	
18	  const { data: userMap } = useQuery({
19	    queryKey: ["admin_users"],
20	    queryFn: async () => {
21	      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
22	      if (error) throw error;
23	      if (!Array.isArray(data)) throw new Error(data?.error || "Failed to load users");
24	      const map: Record<string, string> = {};
25	      data.forEach((u: any) => { map[u.id] = u.email; });
26	      return map;
27	    },
28	    staleTime: 5 * 60 * 1000,
29	  });
30	
31	  // Fetch plan and pack names for display
32	  const { data: planMap } = useQuery({
33	    queryKey: ["admin_plans_map"],
34	    queryFn: async () => {
35	      const { data } = await supabase.from("plans").select("id, name");
36	      const map: Record<string, string> = {};
37	      data?.forEach((p: any) => { map[p.id] = p.name; });
38	      return map;
39	    },
40	    staleTime: 5 * 60 * 1000,
41	  });
42	
43	  const { data: packMap } = useQuery({
44	    queryKey: ["admin_packs_map"],
45	    queryFn: async () => {
46	      const { data } = await supabase.from("credit_packs").select("id, name");
47	      const map: Record<string, string> = {};
48	      data?.forEach((p: any) => { map[p.id] = p.name; });
49	      return map;
50	    },
51	    staleTime: 5 * 60 * 1000,
52	  });
53	
54	  const { data, isLoading } = useQuery({
55	    queryKey: ["admin_payments", page],
56	    queryFn: async () => {
57	      const from = page * PAGE_SIZE;
58	      const to = from + PAGE_SIZE - 1;
59	      const { data, error, count } = await supabase
60	        .from("payments")
61	        .select("*", { count: "exact" })
62	        .order("created_at", { ascending: false })
63	        .range(from, to);
64	      if (error) throw error;
65	      return { payments: data, total: count ?? 0 };
66	    },
67	  });
68	
69	  const totalPages = Math.ceil((data?.total ?? 0) / PAGE_SIZE);
70	
71	  const statusVariant = (status: string) => {
72	    switch (status) {
73	      case "paid": return "success" as const;
74	      case "created": return "warning" as const;
75	      case "failed": return "destructive" as const;
76	      default: return "secondary" as const;
77	    }
78	  };
79	
80	  const statusLabel = (status: string) => {
81	    switch (status) {
82	      case "paid": return "Successful";
83	      case "created": return "Unpaid";
84	      case "failed": return "Failed";
85	      case "dismissed": return "Cancelled";
86	      default: return "Pending";
87	    }
88	  };
89	
90	  const getItemName = (p: any) => {
91	    if (p.plan_id && planMap?.[p.plan_id]) return planMap[p.plan_id];
92	    if (p.pack_id && packMap?.[p.pack_id]) return packMap[p.pack_id];
93	    return "—";
94	  };
95	
96	  const getDodoUrl = (p: any) => {
97	    if (!p.dodo_payment_id) return null;
98	    return `https://app.dodopayments.com/payments/${p.dodo_payment_id}`;
99	  };
100	
101	  const handleExport = () => {
102	    if (!data?.payments?.length) return;
103	    const rows = data.payments.map((p: any) => ({
104	      payment_id: p.dodo_payment_id || p.id,
105	      user_email: userMap?.[p.user_id] || p.user_id,
106	      item: getItemName(p),
107	      amount: `${p.currency} ${(p.amount / 100).toFixed(2)}`,
108	      credits: p.credits_purchased,
109	      gateway: p.payment_gateway || "dodo",
110	      status: statusLabel(p.status),
111	      date: new Date(p.created_at).toISOString(),
112	    }));
113	    exportToCSV(rows, "payments");
114	  };
115	
116	  return (
117	    <div className="space-y-6">
118	      <div className="flex items-center justify-between">
119	        <h2 className="text-xl font-semibold flex items-center gap-2">
120	          <CreditCard className="h-5 w-5 text-primary" />
121	          Payments
122	        </h2>
123	        <Button variant="outline" size="sm" onClick={handleExport} disabled={!data?.payments?.length}>
124	          <Download className="h-4 w-4 mr-1" />CSV
125	        </Button>
126	      </div>
127	      {isLoading ? (
128	        <div className="space-y-2">
129	          {[...Array(5)].map((_, i) => <Skeleton key={i} className="h-12 w-full" />)}
130	        </div>
131	      ) : (
132	        <div className="rounded-md border">
133	          <Table>
134	            <TableHeader>
135	              <TableRow>
136	                <TableHead>Payment ID</TableHead>
137	                <TableHead>User</TableHead>
138	                <TableHead>Item</TableHead>
139	                <TableHead>Amount</TableHead>
140	                <TableHead>Credits</TableHead>
141	                <TableHead>Gateway</TableHead>
142	                <TableHead>Status</TableHead>
143	                <TableHead>Date</TableHead>
144	              </TableRow>
145	            </TableHeader>
146	            <TableBody>
147	              {data?.payments?.length === 0 && (
148	                <TableRow>
149	                  <TableCell colSpan={8} className="text-center text-muted-foreground py-8">No payments recorded yet.</TableCell>
150	                </TableRow>
151	              )}
152	              {data?.payments?.map((p: any) => {
153	                const dodoUrl = getDodoUrl(p);
154	                return (
155	                  <TableRow key={p.id}>
156	                    <TableCell className="font-mono text-xs">
157	                      <div className="flex items-center gap-1">
158	                        {p.dodo_payment_id || p.id?.slice(0, 12) + "…"}
159	                        {dodoUrl && (
160	                          <a href={dodoUrl} target="_blank" rel="noopener noreferrer" title="View on Dodo">
161	                            <ExternalLink className="h-3 w-3 text-primary" />
162	                          </a>
163	                        )}
164	                      </div>
165	                    </TableCell>
166	                    <TableCell className="text-sm max-w-[180px] truncate" title={userMap?.[p.user_id] || p.user_id}>
167	                      {userMap?.[p.user_id] || p.user_id?.slice(0, 8) + "…"}
168	                    </TableCell>
169	                    <TableCell className="text-sm">
170	                      {getItemName(p)}
171	                    </TableCell>
172	                    <TableCell>{p.currency} {(p.amount / 100).toFixed(2)}</TableCell>
173	                    <TableCell>{p.credits_purchased}</TableCell>
174	                    <TableCell>
175	                      <Badge variant="outline" className="text-[11px]">
176	                        {p.payment_gateway === "dodo" ? "Dodo" : p.payment_gateway || "—"}
177	                      </Badge>
178	                    </TableCell>
179	                    <TableCell>
180	                      <Badge variant={statusVariant(p.status)}>{statusLabel(p.status)}</Badge>
181	                    </TableCell>
182	                    <TableCell className="text-sm text-muted-foreground">
183	                      {new Date(p.created_at).toLocaleDateString("en-US", {
184	                        month: "short", day: "numeric", year: "numeric",
185	                        hour: "2-digit", minute: "2-digit",
186	                      })}
187	                    </TableCell>
188	                  </TableRow>
189	                );
190	              })}
191	            </TableBody>
192	          </Table>
193	          {totalPages > 1 && (
194	            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
195	              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
196	              <div className="flex items-center gap-2">
197	                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
198	                  <ChevronLeft className="h-3.5 w-3.5" />
199	                </Button>
200	                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
201	                  <ChevronRight className="h-3.5 w-3.5" />
202	                </Button>
203	              </div>
204	            </div>
205	          )}
206	        </div>
207	      )}
208	    </div>
209	  );
210	};
211	
212	export default PaymentsTab;
